import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Test-Design Skill 仕様書 (日本語)","description":"","frontmatter":{},"headers":[],"relativePath":"SKILL-DESIGN.ja.md","filePath":"SKILL-DESIGN.ja.md"}'),i={name:"SKILL-DESIGN.ja.md"};function l(n,t,o,r,h,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="test-design-skill-仕様書-日本語" tabindex="-1">Test-Design Skill 仕様書 (日本語) <a class="header-anchor" href="#test-design-skill-仕様書-日本語" aria-label="Permalink to &quot;Test-Design Skill 仕様書 (日本語)&quot;">​</a></h1><blockquote><p><a href="./SKILL-DESIGN">🇬🇧 English</a> • <a href="./SKILL-DESIGN.ja">🇯🇵 日本語</a></p></blockquote><p>kiwa が <strong>テスト設計を自動化・標準化する Claude Code skill</strong> を contract layer (Foundry / Hardhat) と dApp e2e layer (Playwright + kiwa fixture) の両方でどう構造化するかの仕様書。 Phase E 実装 PR が参照する SSOT。</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>テスト設計は 3 層で構造化する:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Skill (予定)</th><th>目的</th></tr></thead><tbody><tr><td><strong>1. 汎用テスト設計</strong></td><td><code>/kiwa-design</code></td><td>機能仕様 / API / 画面 / コード / DB schema を入力に、 品質リスク / テスト観点 / テストケース / 優先度 / 自動化方針を出力</td></tr><tr><td><strong>2. テストランナー特化</strong></td><td><code>/kiwa-forge</code> / <code>/kiwa-hardhat</code> / <code>/kiwa-play</code> (refactor)</td><td>Layer 1 の出力を実 <code>*.t.sol</code> / <code>*.test.ts</code> / <code>*.spec.ts</code> に変換</td></tr><tr><td><strong>3. ドキュメント</strong></td><td>docs cookbook + skill reference</td><td>layer 連携で完全な dApp test pyramid を実現する手順を示す</td></tr></tbody></table><p>1 回の skill 起動で 5 段階フローを完走:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[Skill 起動] --&gt; B[入力を整理]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[品質リスクを洗い出す]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[テスト観点を選ぶ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[テストケースを作る]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; F[優先度を付ける]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F --&gt; G[自動化方針を決める]</span></span></code></pre></div><hr><h2 id="なぜこの仕様書が必要か" tabindex="-1">なぜこの仕様書が必要か <a class="header-anchor" href="#なぜこの仕様書が必要か" aria-label="Permalink to &quot;なぜこの仕様書が必要か&quot;">​</a></h2><p>テスト設計は本質的に <strong>仕様策定の作業</strong> であり、 コーディングではない。 各開発者が機能ごとに「何をテストするか」をゼロから書き直すと工数が爆発する。</p><p>kiwa は既に <code>/kiwa-play</code> の <code>Step 1.5</code> で「先に仕様書を書く」設計が偽陽性を減らし実装を加速することを証明済。 Phase E はこの pattern を <strong>contract / integration / e2e の各層</strong> と <strong>Foundry / Hardhat / Playwright の各ランナー</strong> に汎用化する。</p><p>Phase E は新しいテスト分類を発明するわけではない。 Claude Code skill が以下を一貫して出力する基準を作る:</p><ul><li>リスクベースのテスト選定</li><li>観点網羅 (正常 / 異常 / 境界値 / 状態遷移 / 権限 / バリデーション / 冪等性 / 並行処理 / 性能 / セキュリティ)</li><li><code>TC-XXX</code> 表形式の統一テストケース</li><li>優先度 (高 / 中 / 低) を影響度基準で</li><li>自動化推奨 (自動 / 手動 + 推奨ツール)</li></ul><h2 id="_5-段階-skill-フロー" tabindex="-1">5 段階 skill フロー <a class="header-anchor" href="#_5-段階-skill-フロー" aria-label="Permalink to &quot;5 段階 skill フロー&quot;">​</a></h2><p>全てのテスト設計 skill は以下のセクションを <strong>この順</strong> で生成する。</p><h3 id="_1-入力を整理する" tabindex="-1">1. 入力を整理する <a class="header-anchor" href="#_1-入力を整理する" aria-label="Permalink to &quot;1. 入力を整理する&quot;">​</a></h3><p>対象機能について以下を列挙:</p><ul><li>機能名 + 1 文要約</li><li>ユーザー操作 (UI / CLI / API クライアントの観点)</li><li>API 契約 (HTTP method / path / request / response)</li><li>DB 更新 (触れる table、 変更する column、 transaction 境界)</li><li>権限モデル (role、 scope、 multi-tenant 隔離)</li><li>外部連携 (third-party API、 blockchain RPC、 webhook)</li><li>失敗 mode (timeout、 retry、 partial state、 idempotency key)</li></ul><p>仕様に欠けている項目があれば出力末尾の <strong>「不足している仕様」</strong> に明記する。 skill が欠落値を勝手に補完してはいけない。</p><h3 id="_2-品質リスクを洗い出す" tabindex="-1">2. 品質リスクを洗い出す <a class="header-anchor" href="#_2-品質リスクを洗い出す" aria-label="Permalink to &quot;2. 品質リスクを洗い出す&quot;">​</a></h3><p>各入力要素に対し 5 基準でリスクを評価 (高 / 中 / 低):</p><table tabindex="0"><thead><tr><th>基準</th><th>「高」の例</th></tr></thead><tbody><tr><td>売上影響</td><td>チェックアウト / 課金 / 決済</td></tr><tr><td>セキュリティ影響</td><td>認証バイパス、 署名偽造</td></tr><tr><td>データ破壊リスク</td><td>不可逆 write、 soft delete なし</td></tr><tr><td>利用頻度</td><td>全 page load、 全 transaction</td></tr><tr><td>過去障害履歴</td><td>過去 6 ヶ月で bug 報告あり</td></tr></tbody></table><p>skill は <strong>リスク要約 table</strong> を出力し、 Step 3 で参照する。</p><h3 id="_3-テスト観点を選ぶ" tabindex="-1">3. テスト観点を選ぶ <a class="header-anchor" href="#_3-テスト観点を選ぶ" aria-label="Permalink to &quot;3. テスト観点を選ぶ&quot;">​</a></h3><p>各機能に対し以下 13 観点から該当するものを選択 (1-11 共通、 12-13 は e2e layer 必須):</p><table tabindex="0"><thead><tr><th>#</th><th>観点</th><th>適用</th></tr></thead><tbody><tr><td>1</td><td>正常系</td><td>常に</td></tr><tr><td>2</td><td>異常系</td><td>外部依存があれば必須</td></tr><tr><td>3</td><td>境界値</td><td>数値入力 / 文字列長 / 時間範囲</td></tr><tr><td>4</td><td>状態遷移</td><td>state machine / status field / 有限 state</td></tr><tr><td>5</td><td>権限</td><td>認証ゲート / role-based UI</td></tr><tr><td>6</td><td>入力バリデーション</td><td>user 入力 / API payload</td></tr><tr><td>7</td><td>冪等性</td><td>webhook / payment / blockchain tx</td></tr><tr><td>8</td><td>並行処理</td><td>race condition / multi-tab / multi-user</td></tr><tr><td>9</td><td>性能</td><td>高負荷 endpoint / 大 payload</td></tr><tr><td>10</td><td>セキュリティ</td><td>認証 / 署名 / 暗号化 / secret 管理</td></tr></tbody></table><p>選択した観点を Step 4 のテストケースカテゴリにする。</p><h3 id="_4-テストケースを作る" tabindex="-1">4. テストケースを作る <a class="header-anchor" href="#_4-テストケースを作る" aria-label="Permalink to &quot;4. テストケースを作る&quot;">​</a></h3><p>各テストケースは統一 table の 1 行:</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>テスト ID</td><td><code>TC-001</code></td></tr><tr><td>テストレベル</td><td>単体 / 統合 / E2E</td></tr><tr><td>テスト観点</td><td>境界値</td></tr><tr><td>前提条件</td><td>ユーザーがログイン済み</td></tr><tr><td>入力値</td><td>文字数が上限値ちょうどの名前</td></tr><tr><td>操作手順</td><td><code>PUT /api/profile</code> を実行する</td></tr><tr><td>期待結果</td><td>200 OK、 DB に正しく正規化された値が保存される</td></tr><tr><td>優先度</td><td>高</td></tr><tr><td>自動化</td><td>推奨</td></tr></tbody></table><p>skill は 1 ケース 1 行を出力。 観点ごとにグループ化し、 グループ内は優先度順。</p><h3 id="_5-優先度付け-自動化方針" tabindex="-1">5. 優先度付け + 自動化方針 <a class="header-anchor" href="#_5-優先度付け-自動化方針" aria-label="Permalink to &quot;5. 優先度付け + 自動化方針&quot;">​</a></h3><p>優先度は Step 2 のリスク要約 + Step 3 の観点で決定:</p><ul><li><strong>高</strong>: 売上 / セキュリティ / データ破壊 のいずれかが「高」</li><li><strong>中</strong>: 利用頻度 / 過去障害 のいずれかが「高」</li><li><strong>低</strong>: 全基準「低」</li></ul><p>自動化のデフォルト方針 (テストレベル別):</p><ul><li><strong>単体テスト</strong>: 常に自動化 (fast feedback、 deterministic)</li><li><strong>統合テスト</strong>: 主要 API path のみ自動化、 edge case の網羅は production critical なものだけ</li><li><strong>E2E テスト</strong>: 重要導線 (login / checkout / on-chain transaction) だけ自動化、 まれな flow は手動確認に回す</li></ul><p>skill の最終出力には以下を追記:</p><ul><li>「自動化推奨テスト」 — 優先度順</li><li>「手動確認でよいテスト」 — 各ケース理由付き</li><li>「不足している仕様」 — skill が解消できなかった事項を bullet</li></ul><h2 id="出力フォーマット" tabindex="-1">出力フォーマット <a class="header-anchor" href="#出力フォーマット" aria-label="Permalink to &quot;出力フォーマット&quot;">​</a></h2><p>全てのテスト設計 skill はこの markdown skeleton を生成:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 対象機能</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 仕様の要約</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 主な品質リスク</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 推奨テスト構成</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## テスト観点一覧</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## テストケース一覧</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 自動化すべきテスト</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 手動確認でよいテスト</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 不足している仕様</span></span></code></pre></div><p>9 section 全て必須。 順序固定。 skill は空の <code>(なし)</code> placeholder を返してでも section を省略してはいけない。</p><h2 id="layer-2-特化" tabindex="-1">Layer 2 特化 <a class="header-anchor" href="#layer-2-特化" aria-label="Permalink to &quot;Layer 2 特化&quot;">​</a></h2><p>Layer 1 (<code>/kiwa-design</code>) が完了したら、 Layer 2 skill が汎用出力をランナー固有 code に変換する:</p><table tabindex="0"><thead><tr><th>Layer 2 skill</th><th>変換先</th></tr></thead><tbody><tr><td><code>/kiwa-forge</code></td><td><code>test/*.t.sol</code>、 <code>forge test</code> 実行、 <code>forge coverage</code> 評価</td></tr><tr><td><code>/kiwa-hardhat</code></td><td><code>test/*.test.ts</code>、 <code>npx hardhat test</code> 実行、 <code>hardhat-coverage</code> 評価</td></tr><tr><td><code>/kiwa-play</code> (refactored)</td><td><code>tests/*.spec.ts</code> + <code>tests/prepare-env.ts</code>、 Playwright 実行、 4 round flake check</td></tr></tbody></table><p>各 Layer 2 skill は Layer 1 の仕様 file (<code>.context/spec/test-spec-{module}.md</code>) を入力にして実装を出力。 Layer 1 の仕様 file が design と implementation の契約として機能する。</p><h2 id="skill-prompt-テンプレ" tabindex="-1">Skill prompt テンプレ <a class="header-anchor" href="#skill-prompt-テンプレ" aria-label="Permalink to &quot;Skill prompt テンプレ&quot;">​</a></h2><p>全テスト設計 skill が <code>SKILL.md</code> で使う共通 skeleton:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>あなたはアプリケーションテスト設計の専門家です。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>入力された仕様、 コード、 API 定義、 画面情報をもとに、 品質リスクを洗い出し、 必要なテスト項目を作成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>必ず以下を実施してください:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 仕様を要約する</span></span>
<span class="line"><span>2. 品質リスクを洗い出す</span></span>
<span class="line"><span>3. 単体テスト / 統合テスト / E2E テストに分類する</span></span>
<span class="line"><span>4. 観点を確認: 正常系 / 異常系 / 境界値 / 状態遷移 / 権限 / セキュリティ / 性能 / 回帰</span></span>
<span class="line"><span>5. テストケースごとに 前提条件 / 入力値 / 操作手順 / 期待結果 / 優先度 / 自動化可否 を出す</span></span>
<span class="line"><span>6. 仕様が不足している場合は不足点を明記する</span></span>
<span class="line"><span>7. 重要度が高いテストから順番に並べる</span></span></code></pre></div><p>Layer 2 skill はこの prompt をランナー固有指示で拡張 (例: 「Layer 1 ケースを Foundry <code>forge test</code> パターンに変換、 観点 = 境界値の場合は invariant / fuzz を活用」)。</p><h2 id="このフォーマットが活きる用途" tabindex="-1">このフォーマットが活きる用途 <a class="header-anchor" href="#このフォーマットが活きる用途" aria-label="Permalink to &quot;このフォーマットが活きる用途&quot;">​</a></h2><p>同じ 9 section 出力で以下 4 レビュー活動を全てカバー:</p><table tabindex="0"><thead><tr><th>活動</th><th>この仕様書が活きる場面</th></tr></thead><tbody><tr><td>設計レビュー</td><td>実装着手前にテスト計画をレビューで検証</td></tr><tr><td>実装前レビュー</td><td>TDD 流に「先にテストを書く」が仕様書から直接できる</td></tr><tr><td>PR レビュー</td><td>reviewer が「高優先度ケースが全て PR に含まれている」を確認</td></tr><tr><td>QA 観点チェック</td><td>QA team が ad-hoc な探索でなく分類済 checklist で確認</td></tr></tbody></table><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Scope</th><th>対象 file</th></tr></thead><tbody><tr><td><strong>E-1</strong></td><td>SKILL-DESIGN.md 仕様書 (本文書)</td><td><code>docs/SKILL-DESIGN.md</code></td></tr><tr><td><strong>E-2</strong></td><td><code>/kiwa-design</code> skill (Layer 1)</td><td><code>.claude/skills/kiwa-design/</code></td></tr><tr><td><strong>E-3</strong></td><td><code>/kiwa-play</code> refactor (Layer 2 e2e)</td><td>既存 skill に Layer 1 統合</td></tr><tr><td><strong>E-4</strong></td><td><code>/kiwa-forge</code> skill</td><td><code>.claude/skills/kiwa-forge/</code></td></tr><tr><td><strong>E-5</strong></td><td><code>/kiwa-hardhat</code> skill</td><td><code>.claude/skills/kiwa-hardhat/</code></td></tr><tr><td><strong>E-6</strong></td><td>layer 連携の cookbook 章</td><td><code>docs/{ja,en}/cookbook/kiwa-design-flow.md</code></td></tr></tbody></table><p>Phase は D → A → B 段階: 仕様書 → 最も価値ある skill (Layer 1) → 既存 e2e skill への統合、 その後 Foundry / Hardhat runner を community contribution で。</p><h2 id="スコープ外" tabindex="-1">スコープ外 <a class="header-anchor" href="#スコープ外" aria-label="Permalink to &quot;スコープ外&quot;">​</a></h2><ul><li>テスト実行スケジューリング (CI 統合はユーザーの CI tool に任せる)</li><li>mutation testing / formal verification (別 tool)</li><li>テストデータ生成ライブラリ (faker / fast-check / fuzz harness を利用者が選択)</li><li>skill 間メモリ / 状態 (各 skill 起動は stateless、 <code>.context/spec/</code> artifact だけが optional な永続化)</li></ul><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="./MOCK-DESIGN"><code>docs/MOCK-DESIGN.md</code></a> — wallet / SDK mock 精度仕様 (「何を fake するか」の関連概念)</li><li><a href="./../.claude/skills/kiwa-play/SKILL"><code>.claude/skills/kiwa-play/SKILL.md</code></a> — 既存 e2e skill (既にこの flow の一部に従っている)</li><li><a href="./../.claude/skills/kiwa-play/references/adversarial-pitfalls"><code>.claude/skills/kiwa-play/references/adversarial-pitfalls.md</code></a> — 偽陽性 self-check</li></ul>`,61)])])}const g=a(i,[["render",l]]);export{k as __pageData,g as default};
